#import "SLSettingsViewController.h"
#import "SLDownloadManager.h"
#import "SLStore.h"
#import "SLSyncService.h"
#import "SLLibraryViewController.h"
#import "SLTheme.h"
#import "SLAuthStore.h"
#import "SLAPI.h"
@implementation SLSettingsViewController
- (void)viewDidLoad{[super viewDidLoad];self.title=@"Аккаунт";self.tableView.backgroundColor=[SLTheme backgroundColor];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.tableView.backgroundColor=[SLTheme backgroundColor];[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 6;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?2:(s==1?4:(s==2?5:(s==3?2:(s==4?3:1))));}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return [NSArray arrayWithObjects:@"Источники",@"Библиотека",@"Читалка",@"Синхронизация GitHub Gist",@"Вход в lib.social",@"Оптимизация",nil][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{if(s==3)return @"Создайте GitHub Personal Access Token с разрешением gist. Токен хранится локально на устройстве.";if(s==4)return @"Токен можно получить в заголовке Authorization запросов сайта. Он сохраняется в Keychain.";if(s==5)return @"Энергосбережение ограничивает одновременную загрузку и уменьшает размер декодируемых изображений.";if(s==2)return @"Режимы: вертикальная лента или постраничное чтение. Направление справа налево удобно для манги.";return nil;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)p{static NSString *ident=@"SLSettingCell";UITableViewCell *c=[t dequeueReusableCellWithIdentifier:ident];if(!c)c=[[[UITableViewCell alloc]initWithStyle:UITableViewCellStyleValue1 reuseIdentifier:ident]autorelease];c.accessoryView=nil;c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;c.detailTextLabel.text=@"";if(p.section==0){c.textLabel.text=p.row==0?@"SlashLib":@"MangaLib";UISwitch *sw=[[[UISwitch alloc]init]autorelease];sw.tag=100+p.row;sw.on=p.row==0?YES:[[NSUserDefaults standardUserDefaults]boolForKey:@"SLMangaLibEnabled"];sw.enabled=p.row!=0;[sw addTarget:self action:@selector(sourceChanged:) forControlEvents:UIControlEventValueChanged];c.accessoryView=sw;c.selectionStyle=UITableViewCellSelectionStyleNone;}else if(p.section==1){NSArray *n=[NSArray arrayWithObjects:@"Избранное",@"Закладки",@"Недавние",@"Загрузки",nil];c.textLabel.text=[n objectAtIndex:p.row];}else if(p.section==2){NSArray *n=[NSArray arrayWithObjects:@"Режим чтения",@"Направление манги (справа налево)",@"Не гасить экран",@"Внешний вид",@"Фон страниц",nil];c.textLabel.text=[n objectAtIndex:p.row];if(p.row==3){NSInteger tm=[[NSUserDefaults standardUserDefaults]integerForKey:@"SLThemeMode"];c.detailTextLabel.text=tm==1?@"Тёмная":(tm==2?@"Авто":@"Светлая");}else if(p.row==0){NSInteger m=[[NSUserDefaults standardUserDefaults]integerForKey:@"SLReadMode"];c.detailTextLabel.text=m==0?@"Лента":@"Страницы";}else if(p.row<3){UISwitch *sw=[[[UISwitch alloc]init]autorelease];sw.tag=200+p.row;sw.on=[[NSUserDefaults standardUserDefaults]boolForKey:p.row==1?@"SLReadRTL":@"SLKeepAwake"];[sw addTarget:self action:@selector(readerOptionChanged:) forControlEvents:UIControlEventValueChanged];c.accessoryView=sw;c.selectionStyle=UITableViewCellSelectionStyleNone;}}else if(p.section==3){c.textLabel.text=p.row==0?@"Токен GitHub":@"Синхронизировать сейчас";c.detailTextLabel.text=p.row==0?([SLAuthStore token]?@"Сохранён":@"Не задана"): @"";}else if(p.section==4){NSArray *authNames=[NSArray arrayWithObjects:@"Токен аккаунта",@"Открыть SlashLib для регистрации",@"Выйти из аккаунта",nil];c.textLabel.text=[authNames objectAtIndex:p.row];if(p.row==0)c.detailTextLabel.text=[SLAuthStore siteToken]?@"Сохранён":@"Не задан";if(p.row==2)c.textLabel.textColor=[UIColor redColor];}else{c.textLabel.text=@"Энергосбережение";UISwitch *sw=[[[UISwitch alloc]init]autorelease];sw.tag=400;sw.on=[[NSUserDefaults standardUserDefaults]boolForKey:@"SLEnergySaving"];[sw addTarget:self action:@selector(energyChanged:) forControlEvents:UIControlEventValueChanged];c.accessoryView=sw;c.selectionStyle=UITableViewCellSelectionStyleNone;}c.textLabel.textColor=(p.section==4&&p.row==2)?[UIColor redColor]:[SLTheme textColor];c.detailTextLabel.textColor=[SLTheme textColor];return c;}
- (void)sourceChanged:(UISwitch *)sw{[[NSUserDefaults standardUserDefaults]setBool:sw.on forKey:@"SLMangaLibEnabled"];[[NSUserDefaults standardUserDefaults]synchronize];}
- (void)energyChanged:(UISwitch *)sw{[[NSUserDefaults standardUserDefaults]setBool:sw.on forKey:@"SLEnergySaving"];[[NSUserDefaults standardUserDefaults]synchronize];}
- (void)readerOptionChanged:(UISwitch *)sw{NSString *key=sw.tag==201?@"SLReadRTL":@"SLKeepAwake";[[NSUserDefaults standardUserDefaults]setBool:sw.on forKey:key];[[NSUserDefaults standardUserDefaults]synchronize];}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)p{[t deselectRowAtIndexPath:p animated:YES];if(p.section==1){SLLibraryKind kind=(SLLibraryKind)p.row;SLLibraryViewController *v=[[[SLLibraryViewController alloc]initWithKind:kind]autorelease];[self.navigationController pushViewController:v animated:YES];}else if(p.section==2&&p.row==3){UIAlertView *theme=[[[UIAlertView alloc]initWithTitle:@"Внешний вид" message:nil delegate:self cancelButtonTitle:@"Отмена" otherButtonTitles:@"Светлая",@"Тёмная",@"Авто (21:00–07:00)",nil]autorelease];theme.tag=31;[theme show];}else if(p.section==2&&p.row==4){UIAlertView *bg=[[[UIAlertView alloc]initWithTitle:@"Фон страниц" message:nil delegate:self cancelButtonTitle:@"Отмена" otherButtonTitles:@"Чёрный",@"Серый",@"Белый",nil]autorelease];bg.tag=32;[bg show];}else if(p.section==2&&p.row==0){UIAlertView *a=[[[UIAlertView alloc]initWithTitle:@"Режим чтения" message:nil delegate:self cancelButtonTitle:@"Отмена" otherButtonTitles:@"Лента",@"Страницы →",@"Страницы ←",nil]autorelease];a.tag=30;[a show];}else if(p.section==3){UIAlertView *a=[[[UIAlertView alloc]initWithTitle:p.row==0?@"GitHub token":@"Синхронизация" message:p.row==0?@"Вставьте Personal Access Token с правом gist.":@"Объединить библиотеку с приватным Gist?" delegate:self cancelButtonTitle:@"Отмена" otherButtonTitles:p.row==0?@"Сохранить":@"Синхронизировать",nil]autorelease];a.tag=p.row==0?20:21;if(p.row==0){a.alertViewStyle=UIAlertViewStyleSecureTextInput;[a textFieldAtIndex:0].text=[SLAuthStore token];}[a show];}else if(p.section==4){if(p.row==0){UIAlertView *a=[[[UIAlertView alloc]initWithTitle:@"Токен lib.social" message:@"Вставьте токен Bearer из заголовка Authorization." delegate:self cancelButtonTitle:@"Отмена" otherButtonTitles:@"Сохранить и проверить",nil]autorelease];a.alertViewStyle=UIAlertViewStyleSecureTextInput;a.tag=40;[a textFieldAtIndex:0].text=[SLAuthStore siteToken];[a show];}else if(p.row==1){[[UIApplication sharedApplication]openURL:[NSURL URLWithString:@"https://slashlib.me/"]];}else{[SLAuthStore setSiteToken:nil];[self.tableView reloadData];}}}
- (void)alertView:(UIAlertView *)a clickedButtonAtIndex:(NSInteger)i{if(i!=1)return;if(a.tag==30){NSInteger mode=(NSInteger)i-1;/* selected action index maps below via button title */NSString *title=[a buttonTitleAtIndex:i];if([title isEqualToString:@"Лента"])mode=0;else if([title isEqualToString:@"Страницы →"])mode=1;else mode=2;[[NSUserDefaults standardUserDefaults]setInteger:mode forKey:@"SLReadMode"];[[NSUserDefaults standardUserDefaults]setBool:(mode==2) forKey:@"SLReadRTL"];[self.tableView reloadData];}else if(a.tag==32){[[NSUserDefaults standardUserDefaults]setInteger:(i-1) forKey:@"SLPageBackground"];}else if(a.tag==31){NSString *title=[a buttonTitleAtIndex:i];NSInteger mode=[title isEqualToString:@"Тёмная"]?1:([title hasPrefix:@"Авто"]?2:0);[[NSUserDefaults standardUserDefaults]setInteger:mode forKey:@"SLThemeMode"];[SLTheme apply];[self.tableView reloadData];}else if(a.tag==40){NSString *token=[a textFieldAtIndex:0].text?:@"";[SLAuthStore setSiteToken:token];[self.tableView reloadData];[[SLAPI shared]me:^(id result,NSError *error){NSDictionary *data=[result objectForKey:@"data"];NSString *username=[data objectForKey:@"username"];NSString *message=error?[NSString stringWithFormat:@"Токен сохранён, но проверка не прошла: %@",[error localizedDescription]]:[NSString stringWithFormat:@"Вход выполнен: %@",username?:@"пользователь"];UIAlertView *v=[[[UIAlertView alloc]initWithTitle:@"Аккаунт SlashLib" message:message delegate:nil cancelButtonTitle:@"OK" otherButtonTitles:nil]autorelease];[v show];}];}else if(a.tag==20){NSString *token=[a textFieldAtIndex:0].text?:@"";[SLAuthStore setToken:token];[self.tableView reloadData];}else if(a.tag==21){NSString *token=[SLAuthStore token];[[SLSyncService class]syncWithToken:token completion:^(NSString *message){UIAlertView *v=[[[UIAlertView alloc]initWithTitle:@"GitHub Gist" message:message delegate:nil cancelButtonTitle:@"OK" otherButtonTitles:nil]autorelease];[v show];}];}}
@end
